            return null;
        }
        if (_suppressNextToken) {
            _suppressNextToken = false;
            return delegate.currentToken();
        }
        JsonToken t = delegate.nextToken();
        while ((t == null) && switchToNext()) {
            t = delegate.hasCurrentToken()
                    ? delegate.currentToken() : delegate.nextToken();
        }
        return t;
    }

